const cases = $input.all().map(item => item.json);

const allowedRoutes = [
  'potential_resolved',
  'potential_assisted',
  'customer_required',
  'indeterminate'
];

const invalidCases = cases.filter(item =>
  !allowedRoutes.includes(item.potential_route)
);

if (invalidCases.length > 0) {
  throw new Error(
    `Invalid potential_route values for: ${
      invalidCases
        .map(item => item.conversation_reference || 'unknown')
        .join(', ')
    }`
  );
}

const countByRoute = {};

for (const route of allowedRoutes) {
  countByRoute[route] = cases.filter(
    item => item.potential_route === route
  ).length;
}

const eligibleCases = cases.length;

const potentiallyDeflectedCases =
  countByRoute.potential_resolved +
  countByRoute.potential_assisted;

const potentialDeflectionPercent =
  eligibleCases === 0
    ? 0
    : Number(
        (
          (potentiallyDeflectedCases / eligibleCases) *
          100
        ).toFixed(2)
      );

return [
  {
    json: {
      eligible_cases: eligibleCases,
      route_counts: countByRoute,
      potentially_deflected_cases: potentiallyDeflectedCases,
      potential_deflection_percent: potentialDeflectionPercent

    }
  }
];
